// 1. Get the inputs the AI actually sent
const inputs = $input.all()[0].json;

const title = inputs.title || 'New Event';
const relativeDay = (inputs.relative_day || 'today').toLowerCase().trim();
const startTimeStr = inputs.start_time || '09:00';
const duration = Number(inputs.duration_minutes || 60);

// 2. Parse Time
const [hours, minutes] = startTimeStr.split(':').map(Number);
const now = DateTime.now().setZone('Europe/London');

// 3. Logic to determine Days
let daysToAdd = 0;
if (relativeDay.includes('tomorrow')) {
  daysToAdd = 1;
} else if (relativeDay.includes('after tomorrow') || relativeDay.includes('2 days')) {
  daysToAdd = 2;
} else if (relativeDay.includes('today')) {
  daysToAdd = 0;
} else {
  const weekdays = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
  const targetDayIndex = weekdays.findIndex(d => relativeDay.includes(d));
  if (targetDayIndex !== -1) {
    const currentDayIndex = now.weekday - 1;
    daysToAdd = (targetDayIndex - currentDayIndex + 7) % 7;
    if (daysToAdd === 0) daysToAdd = 7;
  }
}

// 4. Build exact Start and End
const startDateTime = now.plus({ days: daysToAdd }).set({
  hour: isNaN(hours) ? 9 : hours,
  minute: isNaN(minutes) ? 0 : minutes,
  second: 0,
  millisecond: 0
});

const endDateTime = startDateTime.plus({ minutes: isNaN(duration) ? 60 : duration });

// Return strict ISO strings
return `Calculated Dates for "${title}": Start ISO = ${startDateTime.toISO()}, End ISO = ${endDateTime.toISO()}`;

parameters.inputSchema:
={
  "type": "object",
  "properties": {
    "title": {
      "type": "string",
      "description": "The title or subject of the calendar event"
    },
    "relative_day": {
      "type": "string",
      "description": "When the event happens, e.g., 'today', 'tomorrow', 'monday', 'tuesday', 'sunday', etc."
    },
    "start_time": {
      "type": "string",
      "description": "Start time in 24-hour HH:mm format (e.g. 09:00, 14:30)"
    },
    "duration_minutes": {
      "type": "number",
      "description": "Duration of the event in minutes. Defaults to 60 if unspecified."
    }
  },
  "required": ["title", "day_offset", "start_time"]
}
